import{_ as i,H as e,f as t,i as s}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"15 | 打造个人产品（一）：内容驱动搭建book2skills","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么做 book2skills？","slug":"为什么做-book2skills","link":"#为什么做-book2skills","children":[]},{"level":2,"title":"Skill 是怎么从书里“提炼”出来的","slug":"skill-是怎么从书里-提炼-出来的","link":"#skill-是怎么从书里-提炼-出来的","children":[]},{"level":2,"title":"让产品自运营：内链增强","slug":"让产品自运营-内链增强","link":"#让产品自运营-内链增强","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"课后题","slug":"课后题","link":"#课后题","children":[]},{"level":2,"title":"附录","slug":"附录","link":"#附录","children":[]}],"relativePath":"AGI产品经理全栈进化指南/15｜打造个人产品（一）：内容驱动搭建book2skills.md","filePath":"AGI产品经理全栈进化指南/15｜打造个人产品（一）：内容驱动搭建book2skills.md","lastUpdated":1795450950000}'),o={name:"AGI产品经理全栈进化指南/15｜打造个人产品（一）：内容驱动搭建book2skills.md"};function a(n,l,p,k,E,r){return e(),t("div",null,[...l[0]||(l[0]=[s('<h1 id="_15-打造个人产品-一-内容驱动搭建book2skills" tabindex="-1">15 | 打造个人产品（一）：内容驱动搭建book2skills <a class="header-anchor" href="#_15-打造个人产品-一-内容驱动搭建book2skills" aria-label="Permalink to &quot;15 | 打造个人产品（一）：内容驱动搭建book2skills&quot;">​</a></h1><p>你好，我是产品二姐。</p><p>如上一讲所说，接下来两节课，是个人开发者可以轻量上手的两个尝试。和企业相比，个人开发者能撬动的物力、人力资源有限，而且从需求发现到最后的宣传推广全部由 1-2 人负责。因此，如果你是刚刚起步的个人开发者，我建议你的产品，除了有用能解决痛点之外，还要满足以下三个条件中的两个条件：</p><ol><li><p>赛道选择方面： 选一个新且会长期存在的赛道。这里的新不是说别人没做过，而是大部分人才刚刚入场，还没有形成稳定格局。</p></li><li><p>产品设计方面：只需要提供很短链路，就能让用户感受到效果。比如 AI 生图这个领域，个人开发者可以做个人写真照的生成，因为用户可以很快看到效果；但做电商商品详情的生图</p></li></ol><ul><li>就不一定合适了，因为商家想要看到的效果是这个图片能给他带来收入，而商品生图只是电商商家运营过程中的一个小环节，商家单凭几张商品图是不能看出效果的。</li></ul><ol start="3"><li>产品运营方面：产品本身要能自运营。不需要倾注很大的运营成本。</li></ol><p>今天和你分享的案例就是从以上三点出发来做的，也是我自己的产品 book2skills ——一个把书籍转化为 Agent Skill 的内容平台。</p><ul><li>注：book2skills.com 于 2026 年 8 月 7 日 -8 月 20 日期间会有短暂的维护时间，我们会尽快恢复。book2skills 上的所有 skills 已在<a href="https://github.com/simbajigege/book2skills" target="_blank" rel="noreferrer">https://github.com/simbajigege/book2skills</a> 开源，如需 skills，可访问开源仓库获取。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/1.png" alt=""></a></p><p>我用两天时间开发完成最初的版本后，在过去的三个月内，几乎零运营的情况下，流量在慢慢增长。而且，在我的规划中，它只完成了第一步，在把网站“养”一段时间后，我会在现在的版本基础上做升级。尽管目前 book2skills 还不能称为一个成功的产品，但其背后的故事却代表了典型的独立开发者的思维，并且非常适合第一次独立开发的同学体验。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/2.png" alt=""></a></p><p>接下来的内容会涵盖以下三个步骤：</p><ol><li><p>从独立开发者角度，为什么要选择做这个产品，以及背后的产品定位决策。</p></li><li><p>book2skills 是如何实现的，尤其是其中的 skill 是如何通过编排 skill 提炼出来的，这种编排skill 的方法在后续章节中也会用在营销内容生产上，是一种通用的方法。</p></li><li><p>book2skills 是如何做到自运营的。</p></li></ol><p>学完这节课，你能初步体会独立开发者为自己做产品，和在职场为公司做产品相比有哪些不同。如果你有意向独立构建自己的产品，那么不妨带着这个思路，从这节课开始，去寻找类似的机会。</p><h2 id="为什么做-book2skills" tabindex="-1">为什么做 book2skills？ <a class="header-anchor" href="#为什么做-book2skills" aria-label="Permalink to &quot;为什么做 book2skills？&quot;">​</a></h2><p>book2skills 的想法源自一篇阅读量 2.5 万的公众号文章：pdf2app：把书变成可以玩儿的APP，文章受到的关注度也很高，文章中提到前半段是 pdf2skills，就是把 pdf 里的内容转换成 skills，可以让 Agent 使用，于是我萌发了把它产品化的想法。</p><p>但最终决定做这个项目，是考虑了以下几个因素：</p><ol><li>Agent Skill 这个概念属于新赛道，处于快速成长期，且会长期伴随 Agent。</li></ol><p>在我看来，Skills 某种程度上是 Anthropic 继 MCP 后提出的另一个标准，它不止是提示词，而是提示词 + 工具使用的融合，比如你可以在 Skill 里定义脚本，在 skill.md 里写入对工具使用的习惯和原则等等，而且它比 workflow 更加灵活。所以我判断它会长期存在，而不是短期热点。</p><p>现在回头再看 Agent skill 这个关键词在谷歌趋势中的热度，就会发现在当时已经很热的基础上，它的热度依然经历了很长时间的上升，证明了我的判断。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/3.png" alt=""></a></p><p>所以，除了选择刚刚起步的赛道之外，你还要有预判趋势的能力。在后面第五章，我会详细和你分享判断趋势与热度的方法。这里不作详述。</p><ol start="2"><li>书籍是提取 Skill 的天然材料。</li></ol><p>我们知道，Skill 是赋予 Agent 某种技能，书籍自古以来就是沉淀技能的最佳载体。特别是类似教你看财报、做营销等方法论的书籍，本身结构清晰、步骤明确，且经过出版社打磨，比其他类型的文档更适合被提炼成 Skill。而且在人类历史上，有非常多经久不衰的书籍，并不会随着时间流逝和技术进步被淹没。</p><ol start="3"><li>书籍 × 行业，可以形成 SEO/GEO 关键词矩阵。</li></ol><p>SEO（搜索引擎优化）对个人开发者来说，是最便宜的流量获取来源，如果网站的内容好，拿到 Google 搜索的首页排名，意味着每天都能免费吸引大量的用户进入你的网站。当然 SEO并非易事，我们在第五章会详细讲述。</p><p>如果我不考虑 SEO，很可能会把 book2skills 做成一个工具：用户上传一本书，然后拿到一组skill。这样做会有两个问题：</p><ul><li><p>一是开发工作量会十倍增大：比如你要兼容上传文档的各种格式；为了保证 Skill 生成的质量，需要调用 Claude-agent-SDK 这类顶级 Agent；要有专门的云存储来保存用户上传的文档；提供 Skill 的转化任务管理等等。</p></li><li><p>二是你在推广的时候，大概会说：“这是一个能把任何书籍转换成 Skill 的工具”，那么你可以被搜索到的关键词就只有“book to agent skill”“agent skill”“convert book to skill”。作为一个要长期运营的网站，关键词不够丰富，不能形成矩阵效应。</p></li></ul><p>而从 SEO 的视角看，我们需要把书名、行业都当做关键词。比如我会在《一本书读懂财报》的 Skill 页面，去贴合以下关键词或者问题：</p><ul><li><p>《一本书读懂财报》有用吗？</p></li><li><p>如何用《一本书读懂财报》的方法解读 xxx 公司</p></li><li><p>《一本书读懂财报》里帮我判断是否有财务造假？</p></li><li><p>....</p></li></ul><p>假设每本书可以衍生出 10 个问题，那么 N 本书的 Skill，就可以有 10 ✖️ N 个关键词或者问答。从行业来看，我们可以做书籍合集：比如个人理财的 10 本最佳书籍，用户增长的 10 本最佳书籍等。甚至我们也可以去切某些名人，比如巴菲特写的书籍，我可以切 “用巴菲特的方法投资”的主题。</p><p>这样，书籍 ✖️ 行业 ✖️ 名人，可以让你的产品具备强大的自运营效果，随着时间的积累，会自我增长起来。</p><p>所以最终，我把这个产品定位为 Skill 内容平台，而不是一个工具。这种流量驱动产品的思维，和用户驱动产品的思维，是两种完全不同的思路，虽然二者用到的技术是一样的，但换一个视角思考，你会构建完全不同的产品。</p><ol start="4"><li>Skill 库可以长出更大的东西。</li></ol><p>最后一个因素再回来看商业成长性。个人开发者的商业变现主要有广告、订阅收费两种。</p><p>对于 book2skills 来说，随着 Skills 的积累和开源 Agent 框架的成熟，我们可以在 Skill 库上长出垂直行业的 Agent 应用，最终形成“Agent 应用 × 书籍 × 行业”的矩阵。一方面，它可以为行业 Agent 做广告，另一方面可以通过基于 Skill 生长出来的 Agent 做订阅收费。这是一件可以做很久的事。</p><p>综合以上四点，我们看到，个人开发者从最开始就要考虑产品的成长性、开发成本、运营成本等因素，从小切口进入，把 book2skills 定位为内容平台，而不是工具。确定这件事可做之后，接下来最重要的就是内容生产，在这里找到一个通用的方法，从书中提炼出 Skill。</p><h2 id="skill-是怎么从书里-提炼-出来的" tabindex="-1">Skill 是怎么从书里“提炼”出来的 <a class="header-anchor" href="#skill-是怎么从书里-提炼-出来的" aria-label="Permalink to &quot;Skill 是怎么从书里“提炼”出来的&quot;">​</a></h2><p>在这里我会使用 Claude Code 完成这件事情，也借此机会和你介绍，如何通过组合 Skills 构建工作流。因为我们是通过编排 Skill 而提炼出 book-skill，为了避免混淆，接下来的内容中，用 Skill 代表 Claude Code 中使用 Skill，用 book-skill 代表从书中提炼出来的技能。</p><p>首先我想以《一本书读懂财报》的 book-skill 为例，看看效果，也就是在同样的提示词下，使用 Skill 和不使用 Skill 的差别。示例中使用的是对腾讯控股的分析，因为内容太长，我放在这一讲的附录里。我对比了 10 份财报分析，并发给身边的二级投资基金经理，都得到明确的肯定。</p><p>接下来你可以看看《一本书读懂财报》的目录与 book-skill 的内容，并按照我的思路详细对比，体会一下其中的联系，然后我再和你分享我是如何生成这个 book-skill 的。</p><p>我们看到这本书目录的一级标题形成了书籍整体脉络：作者首先介绍了资产负债表、利润表、现金流量表，俗称财务三张表；其次讲了活用三张表；然后讲了影响财务的关键因素是行业；最后综合讲述了，从财务角度看，好公司的标准以及风险控制。</p><p>目录：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/4.png" alt=""></a></p><p>此时你可以假设，如果你看了这本书之后，你期待得到什么样的技能呢，我认为就是会看三张表，能发现其中的漏洞，能根据影响因素综合评价公司好坏，以及背后的风险。</p><p>按照这个思路，我们再来看最终生成的 Skill。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/5.png" alt=""></a></p><p>首先这个 Skill 是总分结构，有一个主 book-skill，有若干个子 book-skill，用 m1-m6 表示，分别代表不同章节里体现的技能；主 book-skill 是一个调度器，并不做具体的工作，而是会根据用户的问题，构建出不同的子 book-skil l 组合，比如用户问的是综合评估，那么就是把 m1-m6 这 6 个 subskill 都走一遍，如果用户只问和利润相关的问题，那就只调用对应 m3- 利润质量验证。</p><p>那么这样的 book-skill 是如何生成的呢，我也依次做了三种尝试，才确定了最终方法。</p><p>第一次尝试——整本直出。直接发送书籍给 Claude code，输入提示词“使用 /skill-creator 把这本书里的内容提取为 Skill”，这里的 /skill-creator 是 Anthropic 发布的元 Skill，也就是生成Skill 的 Skill，元 Skill 是创建 Skill 的基础，关于元 Skill 你可以参考 anthropic 的官方内容，这里不做详述。但是这种方法生成的 book-skill 过于宏观。在仔细阅读书籍内容之后，发现很多精华细节都被漏掉了。</p><p>第二次尝试——按章节出。逐步把每个章节发给 Claude Code，每章生成一个 book-skill，但发现 Skill 过于松散，打破了章节原有的联系。</p><p>第三次尝试——渐进式披露法。受“渐进式披露”思想的影响，第一步首先让 Claude Code 为每一个章节写一段较为详细的综述，包含了章节内容，提到的方法、引用案例（如下图）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/6.png" alt=""></a></p><p>接下来从这份摘要出发，让 Claude Code 决定把书拆成几个独立的子 book-skill，并且从用户出发，感受哪些模块可以进行组合完成用户问题，构建出上述的主 book-skill，也就是那个并不做具体工作的总调度器。最后，让 Claude Code 再生成每个子 book-skill 的详细内容，生成子 book-skill 的时候，就是要求 Claude Code 严格阅读并引用原始文章案例。</p><p>第三阶段后，我们生产的 book-skill 就是既有整体，又有细节的，相对完整体现书籍技能的Skill。你看，渐进式披露这种思想在 AI 工程中可以用在非常多的场景中，希望你能再次体会到这一点。</p><p>当这个核心的生产 book-skill 的 Skill 工作流完成后，我还配套了读书 Skill，发布到网站的Skill，组成了以下 Skill 工作流，我只要输入一本书，就能让 Claude Code 全部完成 book-skill生产和发布过程，这个流程是：</p><ol><li><p>读书——read-book-skill。把 pdf 书籍转换成原文全文.md，并提取章节摘要.md。</p></li><li><p>生成——book-skill-creator。在 skill-creator 的基础上，读取摘要生成主 book-skill 和子book-skill。</p></li><li><p>发布 GitHub——write-skill-repo。把 Skill 发布到开源仓库</p></li><li><p>发布到网页——write-skills-page-content。把 Skill 发布到 book2skills 网站。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/7.png" alt=""></a></p><p>在这里，我们看到用 Skill 组合为工作流，并用于内容生产比原来使用 Coze 等搭建工作流会更加灵活。不过这并不意味着 Skill 能取代工作流。Skill 使用依赖于两个条件：</p><ul><li><p>一是使用 Skill 的 Agent 要很强大，比如类似 Codex、Claude Code；</p></li><li><p>二是模型也要强大，最好高于或和 sonnet 4.6 水平相当的模型。</p></li></ul><p>就像我们在 04 讲提到的，Skill 是一个灵活技能，workflow 是一个严谨的操作手册，只有“老医生 Agent”能用得了技能，而“新手 Agent”只能使用 workflow。那么，如果你在企业自己开发的 Agent 中使用 Skill，要同时提升 Agent 本身的能力，而不止是优化 Skill。</p><p>完成这个 Skill 组成的工作流之后，book2skill 这个平台就初步搭建起来了。接下来我们看这类小产品如何实现内容的自运营。</p><h2 id="让产品自运营-内链增强" tabindex="-1">让产品自运营：内链增强 <a class="header-anchor" href="#让产品自运营-内链增强" aria-label="Permalink to &quot;让产品自运营：内链增强&quot;">​</a></h2><p>作为内容平台，我们需要让每一个 Skill 都成为可被索引、可被发现、彼此关联的节点，这样用户发现一个 Skill 后，还能吸引 ta 看其他的 Skill，比如《一本书读懂财报》的 Skill 的用户，对《怎样选择成长股》也会感兴趣。这部分叫内链建设，我们会在第五章商业化详细讲述，这里你只需要知道链接能促进用户点击即可。</p><p>为了达到目的，我们初步把 book2skills 的内链建设落在两个点上。</p><p>一是用 Collections 承载行业维度</p><p>书籍 × 行业 × Skill 的矩阵，行业这个维度在前端通过 Collections 来体现。</p><p>Collections 是按行业组织的 Skill 合集，比如“财务分析”“投资决策”“市场营销”“个人成长”。每个 Collection 下是这个行业里所有相关书籍提炼出的 Skill。每个 Collection 是一个独立的落地页，有自己的 URL、标题和内容，覆盖“[行业] Agent Skill”这一类关键词。当书籍和行业的组合越来越多，Collection 页面自然积累，搜索覆盖面随之扩大。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/8.png" alt=""></a></p><p>二是 Skill 详情页加相关 Skill 内链</p><p>每个 Skill 有独立的详情页，页面末尾展示“相关 Skill”——来自同一行业或处理相似问题的其他Skill。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/9.png" alt=""></a></p><p>在后续 book2skills 的建设中，还可以增加垂直行业 Agent 的这个设计。长远看，book2skills还留给我很大很大的提升空间。</p><p>到这里，我的这个小案例就讲完了，不知道你是否体会到从“小切口”扩展到“大世界”的个人开发者创作思路呢，如果有的话，你可以思考作为个体，有哪个小切口进入，长期做下去，会产生矩阵式的乘法效应和复利效应的产品呢？</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>最后，我们来总结一下。</p><p>这节课从一个公众号文章的洞察出发，完整走了一遍 book2skills 的产品思路，也是适合个人开发者上手的一类小产品。</p><p>首先，对于个人开发者，要做一个产品，不只是“需求存在”，还要是新赛道、长存在、有自运营支撑，这几点都是你需要考虑的因素。</p><p>其次，在 book2skill 这个实战中，我们完成了一个内容生成工作流。在这里我和你分享了使用Skill 编排工作流的方法，并且再次用到了渐进式披露的思想。你可以合理地将这个方法和思想用在你目前的工作流调整中，比如在第五章的商业化中，我同样会用这个方法为AlphaWiseWin 生成营销内容。</p><p>最后我们通过行业专属页、相关 Skill 的内链，增强了 book2skills 的产品自运营能力，把个人开发者从运营中解放出来，避免有限人力资源的浪费。二者其实都只是 SEO 的技巧之一，我们同样会在下一章系统讲述与 SEO/GEO 相关的所有内容。</p><p>不知道今天这样一个小产品对你产生了哪些启发呢？下一节课，我们会继续带来另外一个适合个人开发者的案例。</p><h2 id="课后题" tabindex="-1">课后题 <a class="header-anchor" href="#课后题" aria-label="Permalink to &quot;课后题&quot;">​</a></h2><p>这节课我们套用今天的三个判断标准做出了适合个人开发者的产品。</p><p>①新赛道但长期存在，②用户能快速感受到效果，③产品本身能自运营</p><p>按照这个标准，找出一个让你感兴趣的方向，写下来：</p><ul><li><p>你想做什么赛道？</p></li><li><p>它会不会有什么乘法效应？</p></li><li><p>它未来还会怎么成长</p></li></ul><p>欢迎你在留言区和我交流。如果觉得有所收获，也可以把课程分享给更多的朋友一起学习。我们下节课见！</p><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><p>文中《一本书教你读懂财报》skill 评测示例：以腾讯控股为例看使用 skill 与不使用 skill 的对比分析。</p><ul><li>使用 skill 的分析</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/10.png" alt=""></a></p><p>不使用 skill 的分析</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/15/11.png" alt=""></a></p>',93)])])}const h=i(o,[["render",a]]);export{g as __pageData,h as default};
